queue=list(csv.DictReader((B/'queue.csv').open(newline='',encoding='utf8')))
status={r['sample_id']:r for r in csv.DictReader((ROOT/'shared-catalogues'/'TARGET-STATUS.csv').open(newline='',encoding='utf8'))}
headers=['sample_id','tic','sample_stratum','physical_verdict','full_review_completion','novelty_status','period_days','period_error_days','primary_epoch_btjd','depth_ppt','limitations','next_check','report']
with (B/'RESULTS.csv').open('w',newline='',encoding='utf8') as fh:
 writer=csv.DictWriter(fh,fieldnames=headers);writer.writeheader()
 for q in queue:
  sid=q['sample_id'];tic=q['tic'];v=ROWS[sid];d=B/tic
  context=json.loads((d/'lead-context.json').read_text())
  assert context['sample_id']==sid and context['tic']==tic
  assert status[sid]['tic']==tic and status[sid]['novelty_status'].startswith('UNKNOWN')
  report=f'# {sid} TIC {tic}: {v["verdict"]}\n\n'
  report+=f'Sealed priority rank {q["priority_rank"]}; {q["sample_stratum"]}. Gaia DR3 {q["gaia_dr3"]}, catalogue novelty UNKNOWN because four positive-control gates failed.\n\n'
  report+=v['evidence']+'\n\n'
  report+=f'Limitations: {v["limitations"]}\n\nNext check: {v["next"]}\n\n'
  report+='Evidence: `lead-context.json` (whole-sector raw SAP coverage, source FITS SHA256 and source packet SHA256), `lead-local-series.json`, `lead-raw-context.png`, `lead-dip-zooms.png`, and `lead-flag-diagnostics.json`. See batch `LEAD-AUDIT.md` and `helper-audit.txt` for the deciding WCS, alternate extraction, recurrence, and null checks. All computations use the hashed original files or hashed fresh TESSCut cutouts.\n'
  (d/'REPORT.md').write_text(report,encoding='utf8')
  writer.writerow(dict(sample_id=sid,tic=tic,sample_stratum=q['sample_stratum'],physical_verdict=v['verdict'],full_review_completion='COMPLETE',novelty_status='UNKNOWN',period_days=v['period'],period_error_days='',primary_epoch_btjd=v['epoch'],depth_ppt=v['depth'],limitations=v['limitations'],next_check=v['next'],report=str(d/'REPORT.md')))
print('Wrote',len(queue),'manually adjudicated rows/reports')
